\n-- ============================================================\n-- PHASE 2: pgvector + document_chunks + embeddings + analytics\n-- NOTE: Using 1536-dim (text-embedding-3-small) — Supabase pgvector\n-- HNSW index is capped at 2000 dims;
 3072 falls back to IVFFlat\n-- which requires a minimum row count to build. 1536 gives HNSW + lower storage.\n-- ============================================================\n\nCREATE EXTENSION IF NOT EXISTS vector;
\n\n-- ============================================================\n-- DOCUMENT CHUNKS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS document_chunks (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  document_id uuid NOT NULL REFERENCES knowledge_documents(id) ON DELETE CASCADE,\n  chunk_index int NOT NULL,\n  content text NOT NULL,\n  content_start int,\n  content_end int,\n  page_number int,\n  section_heading varchar(255),\n  metadata jsonb DEFAULT '{}',\n  created_at timestamptz DEFAULT now(),\n  UNIQUE (document_id, chunk_index)\n);
\n\nCREATE INDEX IF NOT EXISTS idx_document_chunks_document ON document_chunks(document_id);
\n\nALTER TABLE document_chunks ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "chunks_select_approved" ON document_chunks FOR SELECT TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM knowledge_documents kd\n      WHERE kd.id = document_id AND kd.status = 'approved'\n    )\n  );
\n\nCREATE POLICY "chunks_insert_admin" ON document_chunks FOR INSERT TO authenticated\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles WHERE id = auth.uid()\n      AND role IN ('admin', 'hse_manager', 'hse_advisor')\n    )\n  );
\n\nCREATE POLICY "chunks_delete_admin" ON document_chunks FOR DELETE TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin'\n    )\n  );
\n\n-- ============================================================\n-- EMBEDDINGS (1536-dim: text-embedding-3-small, Azure ada-002)\n-- ============================================================\nCREATE TABLE IF NOT EXISTS embeddings (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  chunk_id uuid NOT NULL REFERENCES document_chunks(id) ON DELETE CASCADE,\n  embedding vector(1536) NOT NULL,\n  model varchar(50) DEFAULT 'text-embedding-3-small',\n  created_at timestamptz DEFAULT now()\n);
\n\nCREATE INDEX IF NOT EXISTS idx_embeddings_vector\n  ON embeddings USING hnsw (embedding vector_cosine_ops)\n  WITH (m = 16, ef_construction = 64);
\n\nALTER TABLE embeddings ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "embeddings_admin_only" ON embeddings FOR ALL TO authenticated\n  USING (\n    EXISTS (\n      SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin'\n    )\n  )\n  WITH CHECK (\n    EXISTS (\n      SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'admin'\n    )\n  );
\n\n-- ============================================================\n-- ANALYTICS EVENTS\n-- ============================================================\nCREATE TABLE IF NOT EXISTS analytics_events (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id uuid NOT NULL DEFAULT auth.uid() REFERENCES auth.users(id),\n  event_type varchar(50) NOT NULL\n    CHECK (event_type IN (\n      'chat_query', 'safety_escalation', 'governance_flag',\n      'document_viewed', 'document_searched',\n      'risk_assessment_created', 'risk_assessment_approved',\n      'toolbox_talk_generated', 'toolbox_talk_conducted',\n      'observation_submitted', 'observation_closed',\n      'ptw_submitted', 'ptw_approved',\n      'incident_reported', 'incident_investigated',\n      'module_completed', 'quiz_passed',\n      'login', 'voice_query'\n    )),\n  session_id uuid,\n  metadata jsonb DEFAULT '{}',\n  created_at timestamptz DEFAULT now()\n);
\n\nCREATE INDEX IF NOT EXISTS idx_analytics_events_user ON analytics_events(user_id);
\nCREATE INDEX IF NOT EXISTS idx_analytics_events_type ON analytics_events(event_type);
\nCREATE INDEX IF NOT EXISTS idx_analytics_events_created ON analytics_events(created_at DESC);
\n\nALTER TABLE analytics_events ENABLE ROW LEVEL SECURITY;
\n\nCREATE POLICY "analytics_insert_own" ON analytics_events FOR INSERT TO authenticated\n  WITH CHECK (auth.uid() = user_id);
\n\nCREATE POLICY "analytics_select_own" ON analytics_events FOR SELECT TO authenticated\n  USING (\n    auth.uid() = user_id\n    OR EXISTS (\n      SELECT 1 FROM profiles WHERE id = auth.uid()\n      AND role IN ('admin', 'hse_manager', 'auditor')\n    )\n  );
\n\n-- ============================================================\n-- HELPER: pgvector similarity search RPC function\n-- ============================================================\nCREATE OR REPLACE FUNCTION match_document_chunks(\n  query_embedding vector(1536),\n  match_threshold float DEFAULT 0.70,\n  match_count int DEFAULT 5,\n  filter_asset_type text DEFAULT NULL\n)\nRETURNS TABLE (\n  chunk_id uuid,\n  document_id uuid,\n  content text,\n  section_heading varchar,\n  page_number int,\n  document_title varchar,\n  document_code varchar,\n  risk_level varchar,\n  similarity float\n)\nLANGUAGE sql STABLE\nAS $$\n  SELECT\n    dc.id AS chunk_id,\n    dc.document_id,\n    dc.content,\n    dc.section_heading,\n    dc.page_number,\n    kd.title AS document_title,\n    kd.document_code,\n    kd.risk_level,\n    1 - (e.embedding <=> query_embedding) AS similarity\n  FROM embeddings e\n  JOIN document_chunks dc ON dc.id = e.chunk_id\n  JOIN knowledge_documents kd ON kd.id = dc.document_id\n  WHERE kd.status = 'approved'\n    AND (\n      filter_asset_type IS NULL\n      OR kd.asset_types @> ARRAY[filter_asset_type]\n      OR array_length(kd.asset_types, 1) IS NULL\n    )\n    AND (1 - (e.embedding <=> query_embedding)) >= match_threshold\n  ORDER BY similarity DESC\n  LIMIT match_count;
\n$$;
\n;
